procedure DrivingStats {
  about "Track monthly learner statistics"
  policy DrivingPolicy
  sheet Learners "Learners" { learner: Text, phone: Phone, lessons_left: Number, test_date: Date, status: Text, license_no: Text private }
  sheet Stats "Stats" { day: Date, passed: Number }
  trigger every month at 09:00

  let all = fetch Learners
  let n = summarize count of all where status == "passed" and days_between(test_date, today()) <= 31
  let m = draft each r in all up to n sms to r.phone: "Hi {r.learner default 'there'}, your test on {r.test_date} was a success! You've passed {r.lessons_left} lessons."
  let ok = request approval of m from owner timeout 2 hours else skip
  send ok
}

