procedure CoffeeStandOrder {
  about "Place weekly coffee order"
  policy CoffeePolicy
  sheet Beans "Beans" { blend: Text, bags: Number, reorder_at: Number, order_bags: Number, roaster: Text, price_per_bag: Money }
  trigger every monday at 07:00

  let beans = fetch Beans
  if beans.reorder_at < today() or beans.order_bags < 40 {
    notify owner "Standing order for {beans.blend} from {beans.roaster} is overdue."
    stop "out of order"
  }
  let bags = beans.bags + 40
  let price = beans.price_per_bag * bags
  let m = draft each r in beans where r.roaster == "Bean Brothers" and r.order_bags < bags and r.reorder_at < today() and r.price_per_bag < price_per_bag_limit(price) and r.blend == "house" do
    let ok = request approval of m from owner timeout 2 hours else stop "order not approved"
    send ok
  }
}

function price_per_bag_limit(price: Money) {
  if price < $10.00 { return $10.00 }
  if price < $20.00 { return $20.00 }
  if price < $30.00 { return $30.00 }
  if price < $40.00 { return $40.00 }
  return price
}
