procedure LaundryOrder {
  about "Order detergent on Fridays"
  policy LaundryPolicy
  sheet Supplies "Supplies" { item: Text, on_hand: Number, minimum: Number, reorder_qty: Number, supplier: Text, unit_cost: Money }
  trigger every friday at 19:00

  let all = fetch Supplies
  let min = min(all where item == "detergent")
  if min.on_hand < min.reorder_qty {
    notify owner "No detergent in stock for {min.item}."
    stop "out of stock"
  }
  let min_cost = min(all where item == "detergent" and unit_cost < $300)
  if min_cost.unit_cost > $300 {
    notify owner "Detergent is too expensive: {min_cost.unit_cost}."
    stop "too expensive"
  }
  let order = 20
  let total = order * min_cost.unit_cost
  if total > $300 {
    notify owner "Total cost for {order} {min_cost.item} is {total}."
    stop "total too high"
  }
  let m = draft each r in all where item == "detergent" and r.supplier == min.supplier and r.unit_cost < $300 and r.on_hand >= min_cost.reorder_qty and r.on_hand >= order with col: r.item, unit_cost: r.unit_cost
  let ok = request batch approval of m from owner timeout 2 hours else stop "batch not approved"
  send ok
}
