  about "Check and update expired memberships"
  policy WashPolicy
  sheet Memberships "Memberships" { member: Text, email: Email, plan: Text, renews: Date, status: Text, card_last4: Text private }
  trigger every day at 23:00

  let expired = filter Memberships where renews < today() and status == "active"
  let n = summarize count of expired
  if n > 100 {
    notify owner "More than 100 memberships to check: {n}."
    stop "too many memberships"
  }
  for each r in expired up to 100 {
    let m = draft email to r.email subject "Your membership is about to expire": "Your membership with {r.plan} is about to expire. Please renew it before {r.renews}."
    let ok = request approval of m from owner timeout 2 hours else stop "message not approved"
    send ok
  }
}

