procedure FloristOrder {
  about "Order flowers"
  policy FloristStockPolicy
  sheet Flowers "Flowers" { flower: Text, stems: Number, minimum: Number, reorder_qty: Number, grower: Text, unit_cost: Money }
  trigger every day at 11:00

  let all = fetch Flowers
  let below = filter all where stems < minimum
  let n = summarize count of below
  if n > 2 {
    notify owner "Too many below minimum: {n}."
    stop "too many below minimum"
  }
  let reorder = summarize count of all where reorder_qty > 0
  if reorder > 0 {
    let reorder_qty = min(reorder, $200)
    let grower = fetch all where grower == below.grower
    let grower_name = fetch all where grower == grower.name
    let m = draft each r in grower up to reorder where r.unit_cost < grower_name.unit_cost: "Hi {r.name default 'there'}, I'm ordering {r.stems} stems of {r.flower} from {r.grower}."
    let ok = request approval of m from owner timeout 2 hours else stop "message not approved"
    send ok
  }
  let m = draft each r in all where r.stems >= minimum: "Hi {r.name default 'there'}, I'm ordering {r.stems} stems of {r.flower} from {r.grower}."
  let ok = request approval of m from owner timeout 2 hours else stop "message not approved"
  send ok
}

