procedure ClinicRefunds {
  about "Handle refund requests within limits"
  policy ClinicRefundPolicy
  sheet RefundRequests "RefundRequests" { request_id: Text, customer: Text, email: Email, amount: Money, purchased: Date, status: Text }
  trigger when new row r in RefundRequests

  if days_between(r.purchased, today()) > 60 {
    notify owner "Refund request {r.request_id} is older than 60 days."
    stop "outside refund window"
  }
  if r.amount > $75.00 {
    notify owner "Refund request {r.request_id} is {r.amount}, over $75. Please review."
    stop "over refund limit"
  }
  if r.amount <= $20 {
    notify owner "Refund request {r.request_id} is {r.amount}, under $20. Please review."
    stop "under refund limit"
  }
  refund r.amount for r.request_id reason "refund request", ask owner first timeout 6 hours else stop "message not approved"
  update r set status = "refunded"
  let m = draft email to r.email: "Hi {r.customer default 'there'}, your refund of {r.amount} has been issued."
  let ok = request approval of m from owner timeout 6 hours else stop "message not approved"
  send ok
}
```

