  let targets = filter all where status == "inactive" and days_between(vaccine_due, today()) <= days
  let n = summarize count of targets
  append Outreach { day: today(), campaign: "comeback", targeted: n }
  let msgs = draft each r in targets up to 100 sms to r.phone: "Hi {r.owner default 'there'}, your pet's vaccine is due soon. Use code COMEBACK15 on your next visit."
  let ok = request batch approval of msgs from owner timeout 1 day else stop "batch not approved"
  send ok
}

